            field: 'month',
            operator: '=',
            value: '2025-12',
          },
        ],
        text: 'Điểm mới nhất',
      },
    ],
    annotationHorizontalLine: {
      yValue: 70,
      text: 'Đường tham chiếu',
    },
    annotationArea: {
      selector: {
        field: 'month',
        operator: 'in',
        value: ['2025-07', '2025-08'],
      },
      text: 'Tăng',
    },
    annotationDifferenceLine: [
      {
        start: {
          selector: [
            {
              field: 'month',
              operator: 'in',
              value: ['2025-07'],
            },
            {
              field: 'net_profit_million',
              operator: '=',
              value: 62.61,
            },
          ],
        },
        end: {
          selector: [
            {
              field: 'month',
              operator: 'in',
              value: ['2025-12'],
            },
          ],
        },
        differenceType: 'absolute',
      },
    ],
    yAxis: {
      autoFormat: false,
      numFormat: {
        type: 'number',
        fractionDigits: 2,
        suffix: ' triệu nhân dân tệ',
      },
    },
    theme: 'swiss-modern',
  }

  const parseRes = zVSeed.safeParse(vseed)
  if (parseRes.success) {
    console.log('zVSeed parse success!!!')
  } else {
    console.error('zVSeed parse error!!!', parseRes)
  }

  return <SimpleVSeedRender vseed={vseed} />
}





